package com.atlasiq.twin;
import com.atlasiq.intelligence.*;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class AdrSuggestionService {private final ArchitectureDiffService diffs;public AdrSuggestionService(ArchitectureDiffService d){diffs=d;}public List<Suggestion> suggest(String from,String to){ArchitectureDiff d=diffs.compare(from,to);List<Suggestion>out=new ArrayList<>();for(QirNode n:d.addedNodes())if(isSignificant(n))out.add(new Suggestion("Introduce "+n.name(),"A new "+n.type()+" architecture component was detected.",List.of(n.id()),"proposed"));if(d.addedEdges().size()>=5)out.add(new Suggestion("Document dependency topology change",d.addedEdges().size()+" new architecture relationships were detected.",d.addedEdges().stream().map(QirEdge::to).distinct().limit(10).toList(),"proposed"));return List.copyOf(out);}private boolean isSignificant(QirNode n){String t=n.type().toLowerCase();return t.contains("database")||t.contains("queue")||t.contains("kafka")||t.contains("cloud")||t.contains("api-contract");}public record Suggestion(String title,String context,List<String>qirRefs,String status){}}
